using UnityEngine;
using UnityEditor;
using UnityEngine.SceneManagement;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var cam = GameObject.Find("IsoCamera") ?? GameObject.Find("Main Camera");
        if (cam == null) { result.Log("no main camera"); return; }
        var c = cam.GetComponent<Camera>();
        if (c == null) { result.Log("no camera component"); return; }
        result.Log("instanceID: " + c.GetEntityId());
        result.Log("name: " + c.name);
        result.Log("enabled: " + c.enabled);
    }
}
